        "body": "Activar saberes previos dialogando brevemente con el grupo sobre qué conocen o han observado acerca de \"Flotación de objetos en agua\". Presentar el propósito de la sesión: Analizar el fenómeno de la flotación comparando distintos objetos en agua, para comprender la relación entre densidad, masa y volumen en los cuerpos sólidos.",
