        "body": "Activar saberes previos dialogando brevemente con el grupo sobre qué conocen o han observado acerca de \"Comprobando la solubilidad\". Presentar el propósito de la sesión: : Observar qué sustancias se disuelven en agua y a qué velocidad.",
