        "body": ": La solubilidad es la capacidad que tiene una sustancia, llamada soluto, de disolverse en otra sustancia, llamada solvente, formando una solución homogénea. Durante la experiencia práctica, el docente orienta el registro ordenado de observaciones y ayuda a contrastar las hipótesis iniciales con los resultados medidos.",
