        "body": "La materia se expande al calentarse. A esto se le llama dilatación térmica. Dilatación térmica de un gas: al aumentar la temperatura, para una cantidad fija de gas y, en condiciones cercanas a una presión constante, el volumen tiende a aumentar. Durante la experiencia práctica, el docente orienta el registro ordenado de observaciones y ayuda a contrastar las hipótesis iniciales con los resultados medidos.",
