        "body": "La presión alteró la producción de gas, modelando desplazamientos del equilibrio, el vinagre (ácido acético) reacciona con bicarbonato para producir sal de acetato de sodio,... Finalizar con una puesta en común breve donde cada equipo justifique su aprendizaje con argumentos científicos claros.",
